import type { Repos } from "../repos";
import { AGENTS, CATEGORIES, VIDEOS } from "./data";

/**
 * Seeds the base catalogue: categories, agents and placeholder videos.
 * Idempotent: does nothing if agents already exist.
 * All of this is simulated content. Nothing here was generated by a model.
 */
export async function seedCatalogue(repos: Repos, opts: { now?: Date } = {}) {
  if ((await repos.agents.count()) > 0) return { seeded: false };
  const now = opts.now ?? new Date();

  const categories = new Map<string, string>();
  for (const c of CATEGORIES) categories.set(c.slug, (await repos.categories.insert(c)).id);

  const agents = new Map<string, string>();
  for (const a of AGENTS) agents.set(a.handle, (await repos.agents.insert(a)).id);

  for (const v of VIDEOS) {
    const agentId = agents.get(v.agent);
    const categoryId = categories.get(v.category);
    if (!agentId || !categoryId) throw new Error(`seed: unknown agent/category for "${v.title}"`);
    const publishedAt = new Date(now.getTime() - v.daysAgo * 86_400_000).toISOString();
    const content = await repos.content.insert({
      agentId,
      categoryId,
      title: v.title,
      description: v.description,
      tags: v.tags,
      durationSeconds: v.duration,
      views: v.views,
      likes: v.likes,
      status: "published",
      source: "seed",
      publishedAt,
      createdAt: publishedAt,
    });
    await repos.activity.log({
      type: "content.published",
      message: `Published "${v.title}"`,
      agentId,
      contentId: content.id,
      simulated: true,
      createdAt: publishedAt,
    });
  }
  return { seeded: true, categories: categories.size, agents: agents.size, videos: VIDEOS.length };
}
